#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    cout << "=========================================" << endl;
    cout << " ⚡ C++ 20 ALGORITHMIC EXECUTION ENGINE" << endl;
    cout << "=========================================" << endl;

    vector<int> data = {42, 12, 88, 5, 67, 34};
    cout << "Original Vector: ";
    for (int v : data) cout << v << " ";
    cout << endl;

    sort(data.begin(), data.end());
    cout << "✓ Sorted Vector: ";
    for (int v : data) cout << v << " ";
    cout << endl;

    cout << "✓ Min Element: " << data.front() << ", Max Element: " << data.back() << endl;
    return 0;
}
